export function getPinyinInitial(text: string): string {
  if (!text) return '#';
  const first = text.charAt(0);
  if (/[a-zA-Z]/.test(first)) return first.toUpperCase();
  if (gb2312Initial[first]) return gb2312Initial[first];
  return '#';
}
